package com.pablo.controlgastos;
import android.app.*;import android.content.*;import android.graphics.Color;import android.os.Bundle;import android.text.InputType;import android.view.*;import android.widget.*;
public class EmailSettingsActivity extends Activity{
 SharedPreferences p;int BG,TEXT,CARD,MUTED;EditText email,pass,host,months;Switch enableCards,enableExpenses,cardAmount,cardText,cardCurrency,cardDate,cardLast4,expenseDate,expenseAmount,expenseCurrency,expenseExact,expenseSimilar;
 public void onCreate(Bundle b){ThemePrefs.applyBaseTheme(this);super.onCreate(b);p=getSharedPreferences(EmailSyncEngine.PREF,MODE_PRIVATE);boolean l=ThemePrefs.isLight(this);BG=l?0xfff6f8f9:0xff0b1218;TEXT=l?0xff1f262c:0xfff2f5f7;CARD=l?Color.WHITE:0xff162029;MUTED=l?0xff5f6970:0xff9ea9b2;build();}
 int dp(int n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}TextView tv(String s,int z){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(TEXT);v.setPadding(dp(8),dp(8),dp(8),dp(8));return v;}Button btn(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);return b;}Switch sw(String s,boolean on){Switch x=new Switch(this);x.setText(s);x.setTextColor(TEXT);x.setChecked(on);x.setPadding(dp(8),dp(6),dp(8),dp(6));return x;}EditText ed(String hint,String val){EditText e=new EditText(this);e.setHint(hint);e.setText(val);e.setTextColor(TEXT);e.setHintTextColor(MUTED);return e;}void title(LinearLayout r,String s){Space sp=new Space(this);r.addView(sp,new LinearLayout.LayoutParams(1,dp(18)));TextView t=tv(s,14);t.setTextColor(MUTED);r.addView(t);}void add(LinearLayout r,View v){r.addView(v,new LinearLayout.LayoutParams(-1,-2));}
 void build(){LinearLayout outer=new LinearLayout(this);outer.setOrientation(LinearLayout.VERTICAL);outer.setBackgroundColor(BG);ScrollView sc=new ScrollView(this);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(dp(18),dp(54),dp(18),dp(18));r.setBackgroundColor(BG);sc.addView(r);outer.addView(sc,new LinearLayout.LayoutParams(-1,0,1));TextView h=tv("Correo y lecturas",27);r.addView(h);r.addView(tv("Una sola cuenta de correo para estados de tarjetas y gastos. Cada función tiene su propia lista blanca, criterios y lectura forzada.",14));
 title(r,"CUENTA DE CORREO");email=ed("Correo",p.getString("email",""));pass=ed("Contraseña de aplicación",SecretStore.get(this));pass.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);host=ed("Servidor IMAP",p.getString("host","imap.gmail.com"));months=ed("Meses hacia atrás",String.valueOf(p.getInt("months_back",6)));months.setInputType(InputType.TYPE_CLASS_NUMBER);add(r,email);add(r,pass);add(r,host);add(r,months);Button test=btn("Probar conexión");add(r,test);test.setOnClickListener(v->testConnection());
 title(r,"TARJETAS DE CRÉDITO");enableCards=sw("Leer estados de tarjetas desde el correo",p.getBoolean("enable_cards",true));add(r,enableCards);Button wlCard=btn("Administrar lista blanca de tarjetas");add(r,wlCard);wlCard.setOnClickListener(v->openWhitelist("card_whitelist","Lista blanca · Tarjetas"));r.addView(tv("Comparación para identificar el PAGO TOTAL. Solo se exigen los criterios activados:",13));cardAmount=sw("Mismo importe total",p.getBoolean("card_cmp_amount",true));cardText=sw("Texto PAGO TC / PAGO DE TARJETA",p.getBoolean("card_cmp_text",true));cardCurrency=sw("Misma moneda",p.getBoolean("card_cmp_currency",true));cardDate=sw("Fecha cercana al vencimiento",p.getBoolean("card_cmp_due_date",false));cardLast4=sw("Últimos 4 dígitos presentes",p.getBoolean("card_cmp_last4",false));for(Switch x:new Switch[]{cardAmount,cardText,cardCurrency,cardDate,cardLast4})add(r,x);Button readCards=btn("Leer estados ahora"),forceCards=btn("Forzar lectura de estados");add(r,readCards);add(r,forceCards);readCards.setOnClickListener(v->runCards(false));forceCards.setOnClickListener(v->confirmForce(true));
 title(r,"GASTOS DESDE CORREO");enableExpenses=sw("Tomar gastos desde el correo",p.getBoolean("enable_expenses",false));add(r,enableExpenses);Button wlExpense=btn("Administrar lista blanca de gastos");add(r,wlExpense);wlExpense.setOnClickListener(v->openWhitelist("expense_whitelist","Lista blanca · Gastos"));r.addView(tv("Comparación para evitar duplicados. Todos los criterios activados deben coincidir:",13));expenseDate=sw("Misma fecha",p.getBoolean("expense_cmp_date",true));expenseAmount=sw("Mismo importe",p.getBoolean("expense_cmp_amount",true));expenseCurrency=sw("Misma moneda",p.getBoolean("expense_cmp_currency",true));expenseExact=sw("Mismo nombre exacto",p.getBoolean("expense_cmp_exact_name",false));expenseSimilar=sw("Nombre parecido",p.getBoolean("expense_cmp_similar_name",true));for(Switch x:new Switch[]{expenseDate,expenseAmount,expenseCurrency,expenseExact,expenseSimilar})add(r,x);expenseExact.setOnCheckedChangeListener((x,on)->{if(on)expenseSimilar.setChecked(false);});expenseSimilar.setOnCheckedChangeListener((x,on)->{if(on)expenseExact.setChecked(false);});Button readExpenses=btn("Leer gastos ahora"),forceExpenses=btn("Forzar lectura de gastos");add(r,readExpenses);add(r,forceExpenses);readExpenses.setOnClickListener(v->runExpenses(false));forceExpenses.setOnClickListener(v->confirmForce(false));
 title(r,"AYUDA");Button help=btn("Ayuda · Correo");add(r,help);help.setOnClickListener(v->help());Button save=btn("Guardar configuración");LinearLayout.LayoutParams slp=new LinearLayout.LayoutParams(-1,-2);slp.setMargins(dp(18),dp(6),dp(18),dp(14));outer.addView(save,slp);save.setOnClickListener(v->{if(save())Toast.makeText(this,"Configuración guardada",Toast.LENGTH_SHORT).show();});setContentView(outer);}
 void openWhitelist(String k,String t){Intent i=new Intent(this,WhitelistActivity.class);i.putExtra("key",k);i.putExtra("title",t);startActivity(i);}boolean save(){int m;try{m=Integer.parseInt(months.getText().toString().trim());}catch(Exception e){Toast.makeText(this,"Revisá los meses hacia atrás",Toast.LENGTH_LONG).show();return false;}if(m<1||m>24){Toast.makeText(this,"Los meses deben estar entre 1 y 24",Toast.LENGTH_LONG).show();return false;}if(enableCards.isChecked()&&p.getString("card_whitelist","sistarbanc|Estado de cuenta").trim().isEmpty()){Toast.makeText(this,"Agregá al menos una regla para tarjetas",Toast.LENGTH_LONG).show();return false;}if(enableExpenses.isChecked()&&p.getString("expense_whitelist","").trim().isEmpty()){Toast.makeText(this,"Agregá al menos una regla para gastos",Toast.LENGTH_LONG).show();return false;}p.edit().putString("email",email.getText().toString().trim()).putString("host",host.getText().toString().trim()).putInt("months_back",m).putBoolean("enable_cards",enableCards.isChecked()).putBoolean("enable_expenses",enableExpenses.isChecked()).putBoolean("card_cmp_amount",cardAmount.isChecked()).putBoolean("card_cmp_text",cardText.isChecked()).putBoolean("card_cmp_currency",cardCurrency.isChecked()).putBoolean("card_cmp_due_date",cardDate.isChecked()).putBoolean("card_cmp_last4",cardLast4.isChecked()).putBoolean("pay_amount",cardAmount.isChecked()).putBoolean("pay_text",cardText.isChecked()).putBoolean("expense_cmp_date",expenseDate.isChecked()).putBoolean("expense_cmp_amount",expenseAmount.isChecked()).putBoolean("expense_cmp_currency",expenseCurrency.isChecked()).putBoolean("expense_cmp_exact_name",expenseExact.isChecked()).putBoolean("expense_cmp_similar_name",expenseSimilar.isChecked()).remove("pass").apply();SecretStore.put(this,pass.getText().toString());return true;}
 void testConnection(){if(!save())return;ProgressDialog d=ProgressDialog.show(this,"Correo","Probando conexión IMAP…",true,false);new Thread(()->{try{EmailSyncEngine.testConnection(this);runOnUiThread(()->{d.dismiss();new AlertDialog.Builder(this).setTitle("Conexión correcta").setMessage("ControlGastos pudo conectarse al correo configurado.").setPositiveButton("Aceptar",null).show();});}catch(Exception e){runOnUiThread(()->{d.dismiss();error(e);});}}).start();}
 void runCards(boolean force){if(!save())return;ProgressDialog d=ProgressDialog.show(this,"Tarjetas",force?"Forzando lectura…":"Leyendo estados…",true,false);new Thread(()->{try{EmailSyncEngine.Result x=EmailSyncEngine.readCards(this,force);runOnUiThread(()->{d.dismiss();new AlertDialog.Builder(this).setTitle("Lectura terminada").setMessage(x.toString()).setPositiveButton("Aceptar",null).show();});}catch(Exception e){runOnUiThread(()->{d.dismiss();error(e);});}}).start();}
 void runExpenses(boolean force){if(!save())return;ProgressDialog d=ProgressDialog.show(this,"Gastos por correo",force?"Forzando lectura…":"Leyendo gastos…",true,false);new Thread(()->{try{EmailSyncEngine.Result x=EmailSyncEngine.readExpenses(this,force);runOnUiThread(()->{d.dismiss();new AlertDialog.Builder(this).setTitle("Lectura terminada").setMessage(x.toString()).setPositiveButton("Aceptar",null).show();});}catch(Exception e){runOnUiThread(()->{d.dismiss();error(e);});}}).start();}
 void confirmForce(boolean cards){new AlertDialog.Builder(this).setTitle(cards?"Forzar lectura de estados":"Forzar lectura de gastos").setMessage("Se volverán a revisar los correos admitidos dentro del período configurado.").setPositiveButton("Forzar",(d,w)->{if(cards)runCards(true);else runExpenses(true);}).setNegativeButton("Cancelar",null).show();}void error(Exception e){new AlertDialog.Builder(this).setTitle("No se pudo leer el correo").setMessage((e.getMessage()==null?e.toString():e.getMessage())+"\n\nEn Gmail se necesita una contraseña de aplicación y la verificación en dos pasos habilitada.").setPositiveButton("Aceptar",null).show();}
 void help(){String t="CONFIGURAR GMAIL\n\nControlGastos NO usa tu contraseña normal de Google. Para crear una contraseña de aplicación primero activá Inicio de sesión/Verificación en dos pasos en tu Cuenta de Google → Seguridad. Después entrá en Contraseñas de aplicaciones, escribí como nombre ‘ControlGastos’, generá la contraseña de 16 caracteres y pegala en ‘Contraseña de aplicación’. Si Google no muestra Contraseñas de aplicaciones, revisá primero que la verificación en dos pasos esté activa.\n\nLISTAS BLANCAS\nTarjetas y gastos son independientes. Entrá con el botón correspondiente y agregá todas las filas que necesites. Cada fila puede filtrar por remitente, asunto y/o texto del mensaje.\n\nPERÍODO\n‘Meses hacia atrás’ limita cuánto historial se revisa.\n\nTARJETAS\nSe extraen cierre, vencimiento, pago contado, compras y cuotas. Los criterios de comparación sirven solo para encontrar el movimiento del PAGO TOTAL.\n\nGASTOS POR CORREO\nAntes de crear un gasto se aplican los criterios activados para evitar duplicados.\n\nLECTURA FORZADA\nVuelve a analizar el período configurado sin quitar la protección contra duplicados.\n\nPRIVACIDAD\nLa contraseña de aplicación se guarda cifrada con Android Keystore.";TextView v=tv(t,15);ScrollView s=new ScrollView(this);s.addView(v);new AlertDialog.Builder(this).setTitle("Ayuda · Correo").setView(s).setPositiveButton("Entendido",null).show();}
}
